 import { BuiltInAgent } from &quot;@copilotkit/runtime/v2&quot; ; 

 const builtInAgent = new BuiltInAgent ({ 
 model: &quot;openai:gpt-5.4-mini&quot; , 
 }); 

 const runtime = new CopilotRuntime ({ 
 agents: { default: builtInAgent }, //, 
 intelligence: new CopilotKitIntelligence ({ 
 apiKey: process.env. INTELLIGENCE_API_KEY ! , 
 }), 
 // Threads are per-user. Without this, every visitor shares one history. 
 identifyUser : ( request ) =&gt; ({ 
 id: request.headers. get ( &quot;x-user-id&quot; ) ?? &quot;anonymous&quot; , 
 name: request.headers. get ( &quot;x-user-name&quot; ) ?? &quot;Anonymous&quot; , 
 }), 
 }); 

 const handler = createCopilotRuntimeHandler ({ 
 runtime, 
 basePath: &quot;/api/copilotkit&quot; , 
 }); 

 export const GET = handler; 
 export const POST = handler; The runtime reads the license key from step 1. Add it to the app that serves
this route: .env.local INTELLIGENCE_API_KEY=your_license_key Running without the Intelligence Platform? Drop the intelligence and identifyUser options and the runtime falls back
to SSE mode with an in-memory runner. Chat still works, but Threads and the
Inspector stay locked and the key is never read. See
